const realm = ${realm_url:doublequote};
const username = (context.panel.elements.find(function(e){return e.id==='matrix_username';})||{}).value || '';
const permission = (context.panel.elements.find(function(e){return e.id==='permission';})||{}).value || 'read';
const trimmed = String(username).trim();
if (!trimmed) {
  context.grafana.notifyWarning(['Username required', 'Pick a Matrix user from the list or type one (e.g. @user:matrix.host).']);
  return;
}
const read = 'true';
const write = permission === 'read_write' ? 'true' : 'false';
const label = permission === 'read_write' ? 'read/write' : 'read';
if (!window.confirm('Grant ' + label + ' to ' + trimmed + ' on ' + realm + '?')) { return; }
(async () => {
try {
  const url = '/api/datasources/proxy/uid/realm-server-operator/_grafana-upsert-realm-user-permission?realm=' + encodeURIComponent(realm)
            + '&user=' + encodeURIComponent(trimmed)
            + '&read=' + read
            + '&write=' + write;
  const r = await fetch(url, { method: 'POST' });
  if (r.ok) {
    context.grafana.notifySuccess(['Permission granted', label + ' granted to ' + trimmed + ' on ' + realm]);
    if (typeof context.grafana.refresh === 'function') { context.grafana.refresh(); }
  } else {
    const txt = await r.text();
    context.grafana.notifyError(['Grant failed', 'HTTP ' + r.status + ': ' + txt]);
  }
} catch (err) {
  context.grafana.notifyError(['Grant failed', String(err)]);
}

})();

const realm = ${realm_url:doublequote};
const username = (context.panel.elements.find(function(e){return e.id==='matrix_username';})||{}).value || '';
const trimmed = String(username).trim();
if (!trimmed) {
  context.grafana.notifyWarning(['Username required', 'Pick a user that holds a permission on this realm.']);
  return;
}
if (!window.confirm('Remove ' + trimmed + ' from ' + realm + '?\n\nThe removal deletes the user\'s permission row on this realm and refuses the user\'s existing realm sessions. The removal does not touch access the user holds through a * or users grant or a realm policy, and does not touch the user\'s Matrix account.')) { return; }
(async () => {
try {
  const url = '/api/datasources/proxy/uid/realm-server-operator/_grafana-remove-realm-user-permission?realm=' + encodeURIComponent(realm)
            + '&user=' + encodeURIComponent(trimmed);
  const r = await fetch(url, { method: 'POST' });
  if (r.ok) {
    context.grafana.notifySuccess(['Permission removed', (await r.json()).message]);
    if (typeof context.grafana.refresh === 'function') { context.grafana.refresh(); }
  } else {
    const txt = await r.text();
    context.grafana.notifyError(['Remove failed', 'HTTP ' + r.status + ': ' + txt]);
  }
} catch (err) {
  context.grafana.notifyError(['Remove failed', String(err)]);
}

})().catch(function (err) { console.error('operator action handler error:', err); });

const realm = ${realm_url:doublequote};
const inFlight = Number((context.panel.elements.find(function(e){return e.id==='in_flight';})||{}).value || 0);
const pending = Number((context.panel.elements.find(function(e){return e.id==='pending';})||{}).value || 0);
const oldest = (context.panel.elements.find(function(e){return e.id==='oldest_pending_human';})||{}).value || 'n/a';
if (inFlight > 0) {
  context.grafana.notifyWarning(['Reindex blocked', 'An indexing job is already in flight for this realm. Wait for it to finish before triggering a new one.']);
  return;
}
if (!window.confirm('Reindex ' + realm + '?\n\nBlast radius:\n  pending: ' + pending + '\n  oldest pending: ' + oldest + '\n\nThis will queue a from-scratch index for this realm only.')) { return; }
(async () => {
try {
  const r = await fetch('/api/datasources/proxy/uid/realm-server-operator/_grafana-reindex?realm=' + encodeURIComponent(realm), { method: 'POST' });
  if (r.ok) {
    context.grafana.notifySuccess(['Reindex queued', 'Started reindex of ' + realm]);
    if (typeof context.grafana.refresh === 'function') { context.grafana.refresh(); }
  } else {
    const txt = await r.text();
    context.grafana.notifyError(['Reindex failed', 'HTTP ' + r.status + ': ' + txt]);
  }
} catch (err) {
  context.grafana.notifyError(['Reindex failed', String(err)]);
}

})().catch(function (err) { console.error('operator action handler error:', err); });

