targets.rawSql:
SELECT
  '${realm_url}' AS realm,
  CASE WHEN EXISTS (
    SELECT 1 FROM realm_user_permissions
     WHERE realm_url = '${realm_url}' AND username = '*' AND read = true
  ) THEN 'yes' ELSE 'no' END AS public_readable,
  CASE WHEN COALESCE(
    (SELECT show_as_catalog FROM realm_metadata WHERE url = '${realm_url}'),
    false
  ) THEN 'yes' ELSE 'no' END AS in_catalog;
